I hope my execution was understandable

> // send the value back to the controller
void Child::sendValue(bool force) {
	// do not send if no samples have been collected, unless instructed otherwise
	if (! _send_without_value && _samples == 0) return;
#if NODEMANAGER_CONDITIONAL_REPORT == ON
	// ignore conditional reporting settings if forced to report or if it is the first run
	if (! force || ! _sensor->getFirstRun()) {
		// if the value is a number
		if (_format != STRING) {
			// if below or above the thresholds, do not send the value
			if (_value < _min_threshold || _value > _max_threshold) return;
			// if the force update timer is over, send the value regardless and restart it
			if (_force_update_timer->isOver()) _force_update_timer->start();
			else {
				// if the value does not differ enough from the previous one, do not send the value
				if (_value > (_last_value - _value_delta) && _value < (_last_value + _value_delta)) {
					return;
				}
			}
		}
		// if the value is a string
		else {
			// if a delta is configured, do not report if the string is the same as the previous one
			if (_value_delta > 0 && strcmp(_value_string, _last_value_string) == 0) {
				return;
			}
		}
	}
	// keep track of the previous value
//	if (_format != STRING) _last_value = _value;
//	else _last_value_string = _value_string;
#endif
	// send the value to the gateway
	if (_format == INT) nodeManager.sendMessage(_child_id,_type,(int)_value);
	if (_format == FLOAT) nodeManager.sendMessage(_child_id,_type,(float)_value,_float_precision);
	if (_format == DOUBLE) nodeManager.sendMessage(_child_id,_type,_value,_float_precision);
	if (_format == STRING) nodeManager.sendMessage(_child_id,_type,_value_string);
	// reset the counters
	reset();
}

> // reset the counters
void Child::reset() { 
	if (_format != STRING) {
		if (_value_processing != NONE) {
			if (_format != STRING) _last_value = _value;
			else _last_value_string = _value_string;
			// reset the counters
			_total = 0;
			_value = 0;
#if NODEMANAGER_EEPROM == ON
			// if the value is supposed to be persisted in EEPROM, save it
			if (_persist_value) saveValue();
#endif
		}
	} else _value_string = "";
	_samples = 0;
}

Just stumbled across the following bug in the framework: https://github.com/openhab/openhab-core/blob/9724045bb60a6b3c31c7c2a91110c7a7d8b0e0ea/bundles/org.openhab.core.thing/src/main/java/org/eclipse/smarthome/core/thing/internal/ThingManagerImpl.java#L353 would never work, because it calls `waitForRunningHandlerRegistrations` which checks in https://github.com/openhab/openhab-core/blob/9724045bb60a6b3c31c7c2a91110c7a7d8b0e0ea/bundles/org.openhab.core.thing/src/main/java/org/eclipse/smarthome/core/thing/internal/ThingManagerImpl.java#L434 the `registerHandlerLock` for a handler. As this set is only created here: https://github.com/openhab/openhab-core/blob/9724045bb60a6b3c31c7c2a91110c7a7d8b0e0ea/bundles/org.openhab.core.thing/src/main/java/org/eclipse/smarthome/core/thing/internal/ThingManagerImpl.java#L348 and never written to this check will always fail. 

Originally, about 4 years in the past the implementation of `registerHandler` wrote to this set: 

```java 
        // this check is needed to prevent infinite loops while a handler is initialized
        if (!registerHandlerLock.contains(thingUID)) {
            registerHandlerLock.add(thingUID);
            ThingHandlerFactory thingHandlerFactory = findThingHandlerFactory(thing.getThingTypeUID());
            if (thingHandlerFactory != null) {
                registerHandler(thing, thingHandlerFactory);
            } else {
                logger.debug("Not registering a handler at this point since no handler factory for thing '{}' found.",
                        thingUID);
            }
            registerHandlerLock.remove(thingUID);
        } else {
            logger.warn("Attempt to register a handler twice for thing {} at the same time will be ignored.", thingUID);
        }
```  
Seems to be lost during some refactorings already back in the ESH era. @kaikreuzer could you please have a look here?

