With the following code there are two symptoms:
- D7 LED does not stay off for as long as I would expect
- Serial "Working offline" messages are paused, overlapping, and generally screwed up

```
int counter = 10000;

void doConnectedWork() {
    digitalWrite(D7, HIGH);
    Serial.println("Working online");
}

void doOfflineWork() {
    digitalWrite(D7, LOW);
    Serial.println("Working offline");
}

bool needConnection() {
    --counter;
    if (0 == counter)
        counter = 10000;
    return (2000 > counter);
}

void setup() {
    pinMode(D7, OUTPUT);
    Serial.begin(9600);
}

void loop() {
    if (needConnection()) {
        if (!Spark.connected())
            Spark.connect();
        doConnectedWork();
    } else {
        if (Spark.connected())
            Spark.disconnect();
        doOfflineWork();
    }
}
```

This is the current implementation (as used on AVR Arduinos without issue)
```cpp
long map(long value, long fromStart, long fromEnd, long toStart, long toEnd)
{
  return (value - fromStart) * (toEnd - toStart) / (fromEnd - fromStart) + toStart;
}
```

But on STM32F µC an unhandled DIV/0 exception will cause a Usage Fault.
So checking for that and acting gracefully would be good.
e.g. like this
```cpp
#include <math.h>

long map(long value, long fromStart, long fromEnd, long toStart, long toEnd)
{
  if (fromEnd == fromStart) return NAN;  // to prevent DIV/0 exception bail out with NaN
  return (value - fromStart) * (toEnd - toStart) / (fromEnd - fromStart) + toStart;
}
```

And if at that, maybe also add a `double` overload
```cpp
double map(double value, double fromStart, double fromEnd, double toStart, double toEnd)
{
  if (fromEnd == fromStart) return NAN;  // to prevent DIV/0 exception bail out with NaN
  return (value - fromStart) * (toEnd - toStart) / (fromEnd - fromStart) + toStart;
}
```

