The following code should be expected to work, however the WiFi.RSSI() call is knocking the Core offline with v0.4.9 firmware.  Works on Photon, and Core stays online if WiFi.RSSI() is not called.  In my limited testing it seems to work ok with v0.3.4 (for 5 minutes).

Code will compile with v0.3.4 - v0.4.9

``` c++
uint32_t MEASUREMENT_INTERVAL = 10000UL;
uint32_t lastTime = 0;
int i = 0;
void setup() {    
    Serial.begin(9600);
}

void loop() {
    if (millis() - lastTime > MEASUREMENT_INTERVAL) {
        lastTime = millis();
        int measurement = WiFi.RSSI(); // works on Photon, not Core
        // int measurement = 0; // works on Core
        String SSID = WiFi.SSID();
        bool connected = WiFi.ready();

        if (connected) {
            Spark.publish("myRSSItest", String("SSID:")+SSID+String(",RSSI:")+String(measurement));
        }

        char buffer[256];
        sprintf(buffer,"%d %s %s %d", ++i, connected?"true":"false", SSID.c_str(), measurement);
        Serial.println(buffer);
    }    
}
```

