```cpp
#include "application.h"

/* executes once at startup */
void setup() {
    pinMode(D7, OUTPUT);
    digitalWrite(D7, LOW);

    digitalWrite(D7, WiFi.clearCredentials() ? HIGH : LOW);
    delay(5000);
    digitalWrite(D7, WiFi.hasCredentials() ? LOW : HIGH);
}

/* executes continuously after setup() runs */
void loop() {

}
