SYSTEM_MODE(MANUAL);

#define CS   A1
#define DC   A0
#define RST  A2  

Adafruit_ST7735 tft = Adafruit_ST7735(CS, DC, RST);

void setup() {
    Serial.begin(115200);
    delay(3000);
    Serial.println("SPI Test Started");

    tft.initG();

    Ethernet.on();
    Ethernet.connect();
    Serial.println("Waiting to connect to Ethernet...");
    while(!Ethernet.ready());
    Serial.println("Connected to Ethernet.");

    Particle.connect();
}

void loop() {
    SPI.lock();
    tft.fillScreen(ST7735_BLACK);
    tft.setCursor(0, 0);
    tft.setTextColor(ST7735_WHITE);
    tft.setTextWrap(true);
    tft.print("HELLO!");
    SPI.unlock();
    delay(300);

    SPI.lock();
    tft.fillScreen(ST7735_BLACK);
    tft.setCursor(0, 0);
    tft.setTextColor(ST7735_WHITE);
    tft.setTextWrap(true);
    tft.print("PARTICLE");    
    SPI.unlock(); 
    delay(300);
}
